import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';
import { uv, mix, time, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry for the card (default 1x1 unit)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: true,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply any cinematic primitives listed in the config
  const primitivesRefs = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params || {});
        primitivesRefs.push(instance);
      }
    }
  }

  // Event handlers container (empty for this node)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitives
    for (const p of primitivesRefs) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    // Dispose GSAP timelines (none created here, but safe guard)
    gsap.globalTimeline.clear();

    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture) {
      loadedTexture.dispose();
    }
  };

  return root;
}
